suppressPackageStartupMessages({
  library(tidyverse)
  library(lubridate)
})

# =========================================================
# Script purpose
# =========================================================
# This script reads and analyzes vertical water flux diagnostics
# generated by TROLL simulations. It can be used to inspect one
# run, compare multiple runs within the same experiment branch,
# or compare runs across different branches (e.g. deep vs shallow
# water table, sandy vs clayey soil, vegetation vs no vegetation).
#
# The script:
# - locates the requested run output files,
# - reads vertical water flux diagnostic tables,
# - reshapes the data into interface-level and layer-level formats,
# - produces faceted diagnostic plots,
# - optionally saves the figures,
# - and summarizes very small or zero Ks / harmonic Ks values.
#
# This is useful for diagnosing hydraulic behavior, identifying
# possible numerical locking, and comparing how different model
# configurations affect vertical water redistribution.

# =========================================================
# 1) PATH HELPER FUNCTIONS
# =========================================================

# Build the base branch path for a given experiment setup
make_branch_path <- function(project_dir, family, vegetation, water_table, texture) {
  file.path(
    project_dir,
    "runs",
    family,
    vegetation,
    water_table,
    texture
  )
}

# Build a configuration list for a single run
make_run_config <- function(
    project_dir,
    family,
    vegetation,
    water_table,
    texture,
    experiment_name,
    out_prefix = "(null)"
) {
  branch_path <- make_branch_path(
    project_dir = project_dir,
    family = family,
    vegetation = vegetation,
    water_table = water_table,
    texture = texture
  )
  
  run_dir <- file.path(branch_path, experiment_name)
  output_dir <- file.path(run_dir, "output")
  
  list(
    branch_path = branch_path,
    run_dir = run_dir,
    output_dir = output_dir,
    flux_path = file.path(output_dir, paste0(out_prefix, "_0_vertical_water_flux.txt")),
    figure_dir = file.path(run_dir, "_plots_vertical_flux"),
    model_name = experiment_name
  )
}

# Build a dataframe for multiple runs under the same branch
make_flux_files_df <- function(
    project_dir,
    family,
    vegetation,
    water_table,
    texture,
    experiment_names,
    out_prefix = "(null)"
) {
  branch_path <- make_branch_path(
    project_dir = project_dir,
    family = family,
    vegetation = vegetation,
    water_table = water_table,
    texture = texture
  )
  
  tibble(
    model_name = experiment_names,
    run_dir = file.path(branch_path, experiment_names),
    experiment_dir = file.path(run_dir, "output"),
    flux_path = file.path(experiment_dir, paste0(out_prefix, "_0_vertical_water_flux.txt"))
  )
}

# Build a dataframe for runs that may belong to different branches
# Required columns in experiment_table:
# family, vegetation, water_table, texture, experiment_name
make_flux_files_df_from_table <- function(project_dir, experiment_table, out_prefix = "(null)") {
  required_cols <- c("family", "vegetation", "water_table", "texture", "experiment_name")
  
  missing_cols <- setdiff(required_cols, names(experiment_table))
  if (length(missing_cols) > 0) {
    stop("experiment_table is missing required column(s): ",
         paste(missing_cols, collapse = ", "))
  }
  
  experiment_table %>%
    mutate(
      branch_path = purrr::pmap_chr(
        list(family, vegetation, water_table, texture),
        ~ file.path(project_dir, "runs", ..1, ..2, ..3, ..4)
      ),
      run_dir = file.path(branch_path, experiment_name),
      experiment_dir = file.path(run_dir, "output"),
      flux_path = file.path(experiment_dir, paste0(out_prefix, "_0_vertical_water_flux.txt")),
      model_name = experiment_name
    )
}

# =========================================================
# 2) FILE READING AND CHECKS
# =========================================================

# Check whether required flux files exist
check_flux_files <- function(files_df) {
  missing_files <- files_df %>%
    filter(!file.exists(flux_path))
  
  if (nrow(missing_files) > 0) {
    stop(
      "These flux files were not found:\n",
      paste(missing_files$flux_path, collapse = "\n")
    )
  }
}

# Read a vertical water flux file and drop empty unnamed columns
read_flux_file <- function(path) {
  df <- read.table(
    path,
    header = TRUE,
    sep = "\t",
    check.names = FALSE,
    fill = TRUE
  )
  
  empty_idx <- which(names(df) == "")
  if (length(empty_idx) > 0) {
    names(df)[empty_idx] <- paste0("empty_col_", seq_along(empty_idx))
  }
  
  df %>%
    select(-starts_with("empty_col_"))
}

# =========================================================
# 3) DATA PROCESSING
# =========================================================

# Read all selected runs into one table
load_all_flux_runs <- function(files_df, start_date) {
  purrr::map_dfr(seq_len(nrow(files_df)), function(i) {
    df <- read_flux_file(files_df$flux_path[i])
    
    if (!"iter" %in% names(df)) {
      stop("Column 'iter' not found in: ", files_df$flux_path[i])
    }
    
    df %>%
      mutate(
        iter = as.numeric(iter),
        model_name = files_df$model_name[i],
        date = start_date + iter,
        sim_year = as.numeric(date - start_date) / 365
      )
  })
}

# Convert flux diagnostics to long format and identify metric/interface/layer
build_flux_long <- function(flux_all, model_levels = NULL, model_labels = NULL) {
  out <- flux_all %>%
    pivot_longer(
      cols = -c(model_name, iter, date, sim_year),
      names_to = "variable",
      values_to = "value"
    ) %>%
    mutate(
      value = as.numeric(value),
      metric = case_when(
        str_detect(variable, "^mean_flux_layers") ~ "mean_flux",
        str_detect(variable, "^mean_abs_flux_layers") ~ "mean_abs_flux",
        str_detect(variable, "^mean_delta_swp_layers") ~ "mean_delta_swp",
        
        str_detect(variable, "^mean_matric_gradient_layers") ~ "mean_matric_gradient",
        str_detect(variable, "^mean_abs_matric_gradient_layers") ~ "mean_abs_matric_gradient",
        str_detect(variable, "^mean_hydraulic_gradient_layers") ~ "mean_hydraulic_gradient",
        str_detect(variable, "^mean_abs_hydraulic_gradient_layers") ~ "mean_abs_hydraulic_gradient",
        
        str_detect(variable, "^mean_ks_harmonic_layers") ~ "mean_ks_harmonic",
        str_detect(variable, "^net_volumetric_change_layers") ~ "net_volumetric_change",
        str_detect(variable, "^gross_volumetric_change_layers") ~ "gross_volumetric_change",
        
        str_detect(variable, "^mean_swp_layer") ~ "mean_swp_layer",
        str_detect(variable, "^mean_ks_layer") ~ "mean_ks_layer",
        TRUE ~ NA_character_
  ),
      interface = str_extract(variable, "\\d+_\\d+"),
      layer = str_extract(variable, "(?<=layer)\\d+")
    )
  
  if (!is.null(model_levels)) {
    if (is.null(model_labels)) {
      out <- out %>%
        mutate(model_name = factor(model_name, levels = model_levels))
    } else {
      out <- out %>%
        mutate(model_name = factor(model_name, levels = model_levels, labels = model_labels))
    }
  }
  
  out
}

# Split long-format data into interface-level and layer-level tables
split_flux_tables <- function(flux_long) {
  df_interface <- flux_long %>%
    filter(!is.na(metric), !is.na(interface)) %>%
    mutate(interface = factor(interface, levels = unique(interface)))
  
  df_layer <- flux_long %>%
    filter(!is.na(metric), !is.na(layer)) %>%
    mutate(layer = factor(layer, levels = unique(layer)))
  
  list(
    df_interface = df_interface,
    df_layer = df_layer
  )
}

# =========================================================
# 4) PLOT FUNCTIONS
# =========================================================

# Plot interface-level variables with one facet per interface
plot_interface_faceted <- function(data, metric_name, title_txt, y_lab, add_zero = FALSE) {
  p <- ggplot(
    data %>% filter(metric == metric_name),
    aes(x = sim_year, y = value)
  ) +
    geom_line(linewidth = 0.3) +
    facet_grid(model_name ~ interface, scales = "free_y") +
    labs(
      title = title_txt,
      x = "Time [years]",
      y = y_lab
    ) +
    theme_bw() +
    theme(
      strip.text = element_text(face = "bold"),
      plot.title = element_text(face = "bold")
    )
  
  if (add_zero) {
    p <- p + geom_hline(yintercept = 0, linetype = 2)
  }
  
  p
}

# Plot layer-level variables with one facet per layer
plot_layer_faceted <- function(data, metric_name, title_txt, y_lab, add_zero = FALSE) {
  p <- ggplot(
    data %>% filter(metric == metric_name),
    aes(x = sim_year, y = value)
  ) +
    geom_line(linewidth = 0.6) +
    facet_grid(model_name ~ layer, scales = "free_y") +
    labs(
      title = title_txt,
      x = "Time [years]",
      y = y_lab
    ) +
    theme_bw() +
    theme(
      strip.text = element_text(face = "bold"),
      plot.title = element_text(face = "bold")
    )
  
  if (add_zero) {
    p <- p + geom_hline(yintercept = 0, linetype = 2)
  }
  
  p
}

# Build all main diagnostic plots
build_flux_plots <- function(df_interface, df_layer) {
  
  p_flux <- plot_interface_faceted(
    df_interface,
    metric_name = "mean_flux",
    title_txt = "Mean flux by interface",
    y_lab = "Mean flux [m s-1]",
    add_zero = TRUE
  )
  
  p_abs_flux <- plot_interface_faceted(
    df_interface,
    metric_name = "mean_abs_flux",
    title_txt = "Mean absolute flux by interface",
    y_lab = "Mean absolute flux [m s-1]"
  )
  
  p_dphi <- plot_interface_faceted(
    df_interface,
    metric_name = "mean_delta_swp",
    title_txt = "Mean delta SWP by interface",
    y_lab = "Mean delta SWP [MPa]",
    add_zero = TRUE
  )
  
  p_matric_gradient <- plot_interface_faceted(
    df_interface,
    metric_name = "mean_matric_gradient",
    title_txt = "Mean matric gradient by interface",
    y_lab = "Mean matric gradient [-]",
    add_zero = TRUE
  )
  
  p_abs_matric_gradient <- plot_interface_faceted(
    df_interface,
    metric_name = "mean_abs_matric_gradient",
    title_txt = "Mean absolute matric gradient by interface",
    y_lab = "Mean absolute matric gradient [-]"
  )
  
  p_hydraulic_gradient <- plot_interface_faceted(
    df_interface,
    metric_name = "mean_hydraulic_gradient",
    title_txt = "Mean hydraulic gradient by interface",
    y_lab = "Mean hydraulic gradient [-]",
    add_zero = TRUE
  )
  
  p_abs_hydraulic_gradient <- plot_interface_faceted(
    df_interface,
    metric_name = "mean_abs_hydraulic_gradient",
    title_txt = "Mean absolute hydraulic gradient by interface",
    y_lab = "Mean absolute hydraulic gradient [-]"
  )
  
  p_kharm <- plot_interface_faceted(
    df_interface,
    metric_name = "mean_ks_harmonic",
    title_txt = "Mean harmonic Ks by interface",
    y_lab = "Mean harmonic Ks [m s-1]"
  )
  
  p_net <- plot_interface_faceted(
    df_interface,
    metric_name = "net_volumetric_change",
    title_txt = "Net volumetric change by interface",
    y_lab = "Net volumetric change [m3]",
    add_zero = TRUE
  )
  
  p_gross <- plot_interface_faceted(
    df_interface,
    metric_name = "gross_volumetric_change",
    title_txt = "Gross volumetric change by interface",
    y_lab = "Gross volumetric change [m3]"
  )
  
  p_swp_layer <- plot_layer_faceted(
    df_layer,
    metric_name = "mean_swp_layer",
    title_txt = "Mean SWP by layer",
    y_lab = "Mean SWP [MPa]"
  )
  
  p_ks_layer <- plot_layer_faceted(
    df_layer,
    metric_name = "mean_ks_layer",
    title_txt = "Mean Ks by layer",
    y_lab = "Mean Ks [m s-1]"
  )
  
  df_panel_interface <- df_interface %>%
    filter(metric %in% c(
      "mean_flux",
      "mean_abs_flux",
      "mean_delta_swp",
      "mean_matric_gradient",
      "mean_abs_matric_gradient",
      "mean_hydraulic_gradient",
      "mean_abs_hydraulic_gradient",
      "mean_ks_harmonic",
      "net_volumetric_change",
      "gross_volumetric_change"
    )) %>%
    mutate(
      metric = factor(
        metric,
        levels = c(
          "mean_flux",
          "mean_abs_flux",
          "mean_delta_swp",
          "mean_matric_gradient",
          "mean_abs_matric_gradient",
          "mean_hydraulic_gradient",
          "mean_abs_hydraulic_gradient",
          "mean_ks_harmonic",
          "net_volumetric_change",
          "gross_volumetric_change"
        ),
        labels = c(
          "Mean flux",
          "Mean absolute flux",
          "Mean delta SWP",
          "Mean matric gradient",
          "Mean absolute matric gradient",
          "Mean hydraulic gradient",
          "Mean absolute hydraulic gradient",
          "Mean harmonic Ks",
          "Net volumetric change",
          "Gross volumetric change"
        )
      )
    )
  
  p_panel_interface <- ggplot(
    df_panel_interface,
    aes(x = sim_year, y = value)
  ) +
    geom_line(linewidth = 0.4) +
    facet_grid(metric + model_name ~ interface, scales = "free_y") +
    labs(
      title = "Vertical water flux diagnostics by configuration and interface",
      x = "Time [years]",
      y = NULL
    ) +
    theme_bw() +
    theme(
      strip.text = element_text(face = "bold", size = 8),
      plot.title = element_text(face = "bold")
    )
  
  df_panel_layer <- df_layer %>%
    filter(metric %in% c("mean_swp_layer", "mean_ks_layer")) %>%
    mutate(
      metric = factor(
        metric,
        levels = c("mean_swp_layer", "mean_ks_layer"),
        labels = c("Mean SWP", "Mean Ks")
      )
    )
  
  p_panel_layer <- ggplot(
    df_panel_layer,
    aes(x = sim_year, y = value)
  ) +
    geom_line(linewidth = 0.5) +
    facet_grid(metric + model_name ~ layer, scales = "free_y") +
    labs(
      title = "Layer-level diagnostics by configuration and layer",
      x = "Time [years]",
      y = NULL
    ) +
    theme_bw() +
    theme(
      strip.text = element_text(face = "bold", size = 8),
      plot.title = element_text(face = "bold")
    )
  
  list(
    p_flux = p_flux,
    p_abs_flux = p_abs_flux,
    p_dphi = p_dphi,
    p_matric_gradient = p_matric_gradient,
    p_abs_matric_gradient = p_abs_matric_gradient,
    p_hydraulic_gradient = p_hydraulic_gradient,
    p_abs_hydraulic_gradient = p_abs_hydraulic_gradient,
    p_kharm = p_kharm,
    p_net = p_net,
    p_gross = p_gross,
    p_swp_layer = p_swp_layer,
    p_ks_layer = p_ks_layer,
    p_panel_interface = p_panel_interface,
    p_panel_layer = p_panel_layer
  )
}
# Save all plots to disk
save_flux_plots <- function(plots, plot_dir) {
  dir.create(plot_dir, recursive = TRUE, showWarnings = FALSE)
  
  ggsave(file.path(plot_dir, "mean_flux_by_interface_faceted.png"), plots$p_flux, width = 14, height = 8, dpi = 300)
  ggsave(file.path(plot_dir, "mean_abs_flux_by_interface_faceted.png"), plots$p_abs_flux, width = 14, height = 8, dpi = 300)
  ggsave(file.path(plot_dir, "mean_delta_swp_by_interface_faceted.png"), plots$p_dphi, width = 14, height = 8, dpi = 300)
  
  ggsave(file.path(plot_dir, "mean_matric_gradient_by_interface_faceted.png"), plots$p_matric_gradient, width = 14, height = 8, dpi = 300)
  ggsave(file.path(plot_dir, "mean_abs_matric_gradient_by_interface_faceted.png"), plots$p_abs_matric_gradient, width = 14, height = 8, dpi = 300)
  ggsave(file.path(plot_dir, "mean_hydraulic_gradient_by_interface_faceted.png"), plots$p_hydraulic_gradient, width = 14, height = 8, dpi = 300)
  ggsave(file.path(plot_dir, "mean_abs_hydraulic_gradient_by_interface_faceted.png"), plots$p_abs_hydraulic_gradient, width = 14, height = 8, dpi = 300)
  
  ggsave(file.path(plot_dir, "mean_ks_harmonic_by_interface_faceted.png"), plots$p_kharm, width = 14, height = 8, dpi = 300)
  ggsave(file.path(plot_dir, "net_volumetric_change_by_interface_faceted.png"), plots$p_net, width = 14, height = 8, dpi = 300)
  ggsave(file.path(plot_dir, "gross_volumetric_change_by_interface_faceted.png"), plots$p_gross, width = 14, height = 8, dpi = 300)
  
  ggsave(file.path(plot_dir, "mean_swp_by_layer_faceted.png"), plots$p_swp_layer, width = 14, height = 8, dpi = 300)
  ggsave(file.path(plot_dir, "mean_ks_by_layer_faceted.png"), plots$p_ks_layer, width = 14, height = 8, dpi = 300)
  
  ggsave(file.path(plot_dir, "vertical_water_flux_panel_interface_faceted.png"), plots$p_panel_interface, width = 18, height = 20, dpi = 300)
  ggsave(file.path(plot_dir, "vertical_water_flux_panel_layer_faceted.png"), plots$p_panel_layer, width = 16, height = 8, dpi = 300)
  
  cat("Saved plots in:\n", plot_dir, "\n")
}
