  print(plots$p_dphi)
  print(plots$p_matric_gradient)
  print(plots$p_abs_matric_gradient)
  print(plots$p_hydraulic_gradient)
  print(plots$p_abs_hydraulic_gradient)
  print(plots$p_kharm)
  print(plots$p_net)
  print(plots$p_gross)
  print(plots$p_swp_layer)
