}
# =========================================================
# 5) DIAGNOSTIC SUMMARY FUNCTIONS
# =========================================================

# Summarize very small or zero mean_ks_layer values
summarize_ks_layers <- function(df_layer) {
  ks_vars <- c(
    "mean_ks_layer0",
    "mean_ks_layer1",
    "mean_ks_layer2",
    "mean_ks_layer3",
    "mean_ks_layer4",
    "mean_ks_layer5"
  )
  
  by_variable <- df_layer %>%
    filter(variable %in% ks_vars) %>%
    group_by(model_name, variable) %>%
    summarise(
      n_total = n(),
      n_non_na = sum(!is.na(value)),
      n_zero_exact = sum(value == 0, na.rm = TRUE),
      pct_zero_exact = 100 * n_zero_exact / n_total,
      n_negative = sum(value < 0, na.rm = TRUE),
      n_na = sum(is.na(value)),
      min_val = if (all(is.na(value))) NA_real_ else min(value, na.rm = TRUE),
      max_val = if (all(is.na(value))) NA_real_ else max(value, na.rm = TRUE),
      min_positive = {
        x <- value[value > 0 & !is.na(value)]
        if (length(x) == 0) NA_real_ else min(x)
      },
      n_lt_1e20 = sum(value > 0 & value < 1e-20, na.rm = TRUE),
      n_lt_1e15 = sum(value > 0 & value < 1e-15, na.rm = TRUE),
      n_lt_1e12 = sum(value > 0 & value < 1e-12, na.rm = TRUE),
      n_lt_1e10 = sum(value > 0 & value < 1e-10, na.rm = TRUE),
      n_lt_1e8  = sum(value > 0 & value < 1e-8,  na.rm = TRUE),
      .groups = "drop"
    ) %>%
    arrange(variable, model_name)
  
  all_layers <- df_layer %>%
    filter(variable %in% ks_vars) %>%
    group_by(model_name) %>%
    summarise(
      min_value_all_layers = min(value, na.rm = TRUE),
      n_zero_exact_all_layers = sum(value == 0, na.rm = TRUE),
      min_positive_all_layers = min(value[value > 0], na.rm = TRUE),
      .groups = "drop"
    )
  
  list(
    by_variable = by_variable,
    all_layers = all_layers
  )
}

# Summarize very small or zero mean_ks_harmonic values
summarize_ksh_interfaces <- function(df_interface) {
  ksh_vars <- c(
    "mean_ks_harmonic_layers0_1",
    "mean_ks_harmonic_layers1_2",
    "mean_ks_harmonic_layers2_3",
    "mean_ks_harmonic_layers3_4",
    "mean_ks_harmonic_layers4_5"
  )
  
  all_interfaces <- df_interface %>%
    filter(variable %in% ksh_vars) %>%
    group_by(model_name) %>%
    summarise(
      min_value_all_interfaces = min(value, na.rm = TRUE),
      n_zero_exact_all_interfaces = sum(value == 0, na.rm = TRUE),
      min_positive_all_interfaces = min(value[value > 0], na.rm = TRUE),
      .groups = "drop"
    )
  
  by_interface <- df_interface %>%
    filter(variable %in% ksh_vars) %>%
    mutate(interface_id = str_extract(variable, "\\d_\\d$")) %>%
    group_by(model_name, interface_id, variable) %>%
    summarise(
      n_total = n(),
      n_non_na = sum(!is.na(value)),
      n_zero_exact = sum(value == 0, na.rm = TRUE),
      pct_zero_exact = 100 * n_zero_exact / n_total,
      n_negative = sum(value < 0, na.rm = TRUE),
      n_na = sum(is.na(value)),
      min_val = if (all(is.na(value))) NA_real_ else min(value, na.rm = TRUE),
      max_val = if (all(is.na(value))) NA_real_ else max(value, na.rm = TRUE),
      min_positive = {
        x <- value[value > 0 & !is.na(value)]
        if (length(x) == 0) NA_real_ else min(x)
      },
      n_lt_1e20 = sum(value > 0 & value < 1e-20, na.rm = TRUE),
      n_lt_1e15 = sum(value > 0 & value < 1e-15, na.rm = TRUE),
      n_lt_1e12 = sum(value > 0 & value < 1e-12, na.rm = TRUE),
      n_lt_1e10 = sum(value > 0 & value < 1e-10, na.rm = TRUE),
      n_lt_1e8  = sum(value > 0 & value < 1e-8,  na.rm = TRUE),
      .groups = "drop"
    ) %>%
    arrange(interface_id, model_name)
  
  smallest_values <- df_interface %>%
    filter(variable %in% ksh_vars) %>%
    arrange(value) %>%
    select(model_name, date, variable, interface, value)
  
  list(
    all_interfaces = all_interfaces,
    by_interface = by_interface,
    smallest_values = smallest_values
  )
}

# Diagnose what happens when harmonic Ks reaches its minimum
diagnose_ksh_floor <- function(df_interface) {
  interfaces <- c("0_1", "1_2", "2_3", "3_4", "4_5")
  
  purrr::map_dfr(interfaces, function(intf) {
    ksh_var  <- paste0("mean_ks_harmonic_layers", intf)
    flux_var <- paste0("mean_abs_flux_layers", intf)
    swp_var  <- paste0("mean_delta_swp_layers", intf)
    
    ksh <- df_interface %>%
      filter(variable == ksh_var) %>%
      select(model_name, date, interface, ksh = value)
    
    flux <- df_interface %>%
      filter(variable == flux_var) %>%
      select(model_name, date, abs_flux = value)
    
    swp <- df_interface %>%
      filter(variable == swp_var) %>%
      select(model_name, date, delta_swp = value)
    
    joined <- ksh %>%
      left_join(flux, by = c("model_name", "date")) %>%
      left_join(swp, by = c("model_name", "date"))
    
    joined %>%
      group_by(model_name, interface) %>%
      summarise(
        min_ksh = min(ksh, na.rm = TRUE),
        n_at_floor = sum(ksh == min(ksh, na.rm = TRUE), na.rm = TRUE),
        mean_abs_flux_at_floor = mean(abs_flux[ksh == min(ksh, na.rm = TRUE)], na.rm = TRUE),
        median_abs_flux_at_floor = median(abs_flux[ksh == min(ksh, na.rm = TRUE)], na.rm = TRUE),
        mean_delta_swp_at_floor = mean(delta_swp[ksh == min(ksh, na.rm = TRUE)], na.rm = TRUE),
        median_delta_swp_at_floor = median(delta_swp[ksh == min(ksh, na.rm = TRUE)], na.rm = TRUE),
        .groups = "drop"
      )
  })
}

diagnose_hydraulic_locking <- function(df_interface) {
  
  interfaces <- sort(unique(na.omit(as.character(df_interface$interface))))
  
  purrr::map_dfr(interfaces, function(intf) {
    
    vars <- tibble(
      variable = c(
        paste0("mean_ks_harmonic_layers", intf),
        paste0("mean_abs_hydraulic_gradient_layers", intf),
        paste0("mean_abs_flux_layers", intf),
        paste0("gross_volumetric_change_layers", intf),
        paste0("mean_delta_swp_layers", intf)
      ),
      var_name = c(
        "ks_harmonic",
        "abs_hydraulic_gradient",
        "abs_flux",
        "gross_volumetric_change",
        "delta_swp"
      )
    )
    
    df_interface %>%
      filter(variable %in% vars$variable) %>%
      left_join(vars, by = "variable") %>%
      select(model_name, date, sim_year, interface, var_name, value) %>%
      pivot_wider(names_from = var_name, values_from = value) %>%
      group_by(model_name, interface) %>%
      summarise(
        median_ks_harmonic = median(ks_harmonic, na.rm = TRUE),
        min_ks_harmonic = min(ks_harmonic, na.rm = TRUE),
        median_abs_hydraulic_gradient = median(abs_hydraulic_gradient, na.rm = TRUE),
        median_abs_flux = median(abs_flux, na.rm = TRUE),
        median_gross_volumetric_change = median(gross_volumetric_change, na.rm = TRUE),
        median_delta_swp = median(delta_swp, na.rm = TRUE),
        
        frac_ksh_lt_1e10 = mean(ks_harmonic < 1e-10, na.rm = TRUE),
        frac_ksh_lt_1e8 = mean(ks_harmonic < 1e-8, na.rm = TRUE),
        frac_abs_gradient_lt_001 = mean(abs_hydraulic_gradient < 0.01, na.rm = TRUE),
        frac_abs_flux_lt_1e12 = mean(abs_flux < 1e-12, na.rm = TRUE),
        
        .groups = "drop"
      )
  })
}
# =========================================================
# 6) MAIN FUNCTION: SAME BRANCH
# =========================================================

# Analyze one or multiple flux runs that belong to the same branch
analyze_vertical_flux_runs <- function(
    project_dir,
    family,
    vegetation = c("veg", "noveg"),
    water_table = c("deepWT", "shallowWT"),
    texture = c("sandy", "clayey"),
    experiment_names,
    mode = 0,                  # 0 = single run, 1 = multiple runs in same branch
    save_plots = FALSE,
    start_date = as.Date("2004-01-01"),
    out_prefix = "(null)",
    model_levels = NULL,
    model_labels = NULL
) {
  vegetation <- match.arg(vegetation)
  water_table <- match.arg(water_table)
  texture <- match.arg(texture)
  
  if (!mode %in% c(0, 1)) {
    stop("'mode' must be 0 or 1.")
  }
  
  if (mode == 0 && length(experiment_names) != 1) {
    stop("For mode = 0, provide exactly one experiment name.")
  }
  
  if (mode == 1 && length(experiment_names) < 2) {
    stop("For mode = 1, provide at least two experiment names.")
  }
  
  if (mode == 0) {
    cfg <- make_run_config(
      project_dir = project_dir,
      family = family,
      vegetation = vegetation,
      water_table = water_table,
      texture = texture,
      experiment_name = experiment_names,
      out_prefix = out_prefix
    )
    
    files_df <- tibble(
      model_name = cfg$model_name,
      run_dir = cfg$run_dir,
      experiment_dir = cfg$output_dir,
      flux_path = cfg$flux_path
    )
    
    plot_dir <- cfg$figure_dir
    
  } else {
    files_df <- make_flux_files_df(
      project_dir = project_dir,
      family = family,
      vegetation = vegetation,
      water_table = water_table,
      texture = texture,
      experiment_names = experiment_names,
      out_prefix = out_prefix
    )
    
    plot_dir <- file.path(
      make_branch_path(project_dir, family, vegetation, water_table, texture),
      "_plots_vertical_flux_compare"
    )
  }
  
  check_flux_files(files_df)
  
  flux_all <- load_all_flux_runs(files_df, start_date = start_date)
  
  flux_long <- build_flux_long(
    flux_all,
    model_levels = model_levels,
    model_labels = model_labels
  )
  
  split_tables <- split_flux_tables(flux_long)
  df_interface <- split_tables$df_interface
  df_layer <- split_tables$df_layer
  
  plots <- build_flux_plots(df_interface, df_layer)
  print_flux_plots(plots)
  
  if (save_plots) {
    save_flux_plots(plots, plot_dir)
  }
  
  ks_summary <- summarize_ks_layers(df_layer)
  ksh_summary <- summarize_ksh_interfaces(df_interface)
  ksh_floor_diag <- diagnose_ksh_floor(df_interface)
  hydraulic_locking_diag <- diagnose_hydraulic_locking(df_interface)
  invisible(list(
    files_df = files_df,
    flux_all = flux_all,
    flux_long = flux_long,
    df_interface = df_interface,
    df_layer = df_layer,
    plots = plots,
    plot_dir = plot_dir,
    ks_summary = ks_summary,
    ksh_summary = ksh_summary,
    ksh_floor_diag = ksh_floor_diag,
    hydraulic_locking_diag = hydraulic_locking_diag
  ))
}

# =========================================================
# 7) MAIN FUNCTION: MIXED BRANCHES
# =========================================================

# Analyze flux runs that may belong to different branches
# experiment_table must contain:
# family, vegetation, water_table, texture, experiment_name
analyze_vertical_flux_runs_table <- function(
    project_dir,
    experiment_table,
    save_plots = FALSE,
    start_date = as.Date("2004-01-01"),
    out_prefix = "(null)",
    model_levels = NULL,
    model_labels = NULL,
    plot_dir = NULL
) {
  files_df <- make_flux_files_df_from_table(
    project_dir = project_dir,
    experiment_table = experiment_table,
    out_prefix = out_prefix
  )
  
  check_flux_files(files_df)
  
  flux_all <- load_all_flux_runs(files_df, start_date = start_date)
  
  flux_long <- build_flux_long(
    flux_all,
    model_levels = model_levels,
    model_labels = model_labels
  )
  
  split_tables <- split_flux_tables(flux_long)
  df_interface <- split_tables$df_interface
  df_layer <- split_tables$df_layer
  
  plots <- build_flux_plots(df_interface, df_layer)
  print_flux_plots(plots)
  
  if (save_plots) {
    if (is.null(plot_dir)) {
      plot_dir <- file.path(project_dir, "runs", "_plots_vertical_flux_compare")
    }
    save_flux_plots(plots, plot_dir)
  }
  
  ks_summary <- summarize_ks_layers(df_layer)
  ksh_summary <- summarize_ksh_interfaces(df_interface)
  ksh_floor_diag <- diagnose_ksh_floor(df_interface)
  hydraulic_locking_diag <- diagnose_hydraulic_locking(df_interface)
  
  invisible(list(
    files_df = files_df,
    flux_all = flux_all,
    flux_long = flux_long,
    df_interface = df_interface,
    df_layer = df_layer,
    plots = plots,
    plot_dir = plot_dir,
    ks_summary = ks_summary,
    ksh_summary = ksh_summary,
    ksh_floor_diag = ksh_floor_diag,
    hydraulic_locking_diag <- hydraulic_locking_diag
    
  ))
}

